const { useState, useRef } = React;
const LOGO_BASE64 ="data:image/png;base64,";
function App() {
  const [data, setData] = useState({
    name: "",
    title: "",
    phone: "",
    email: "",
    calendar: ""
  });

  const sigRef = useRef(null);
  const taRef = useRef(null);

  const handleChange = (e) =>
    setData({ ...data, [e.target.name]: e.target.value });

  const copySignature = () => {
    taRef.current.value = sigRef.current.innerHTML;
    taRef.current.style.display = "block";
    taRef.current.select();
    document.execCommand("copy");
    taRef.current.style.display = "none";
  };

  const downloadHTML = () => {
    const blob = new Blob([sigRef.current.innerHTML], {
      type: "text/html;charset=utf-8"
    });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    const safeName = (data.name || "signature")
      .toUpperCase()
      .replace(/\s+/g, "_");
    a.download = safeName + ".htm";
    a.click();
  };

  return (
    <div>
  <div className="app" style={{ display: "flex", flexDirection: "column", justifyContent: "space-between" }}>
  
  <div style={{ display: "flex", alignItems: "center", gap: "12px", marginBottom: "16px" }}>
  <img
    src="data:image/png;base64,"
    alt="RAMP360"
    style={{ height: "48px" }}
  />
  <h1 style={{ margin: 0 }}>Email Signature</h1>
</div>

      <textarea
        ref={taRef}
        style={{ position: "absolute", left: "-9999px" }}
        readOnly
      />

      {/* STACK INSTEAD OF GRID */}
      <div style={{ display: "flex", flexDirection: "column", flex: 1 }}>

        {/* INPUTS */}
        <div>
          <input name="name" placeholder="Name" onChange={handleChange} />
          <input
            name="title"
            placeholder="Designation"
            onChange={handleChange}
          />
          <input name="phone" placeholder="Phone" onChange={handleChange} />
          <input name="email" placeholder="Email" onChange={handleChange} />
          <input
            name="calendar"
            placeholder="Calendar URL (optional)"
            onChange={handleChange}
          />
        </div>

        {/* PREVIEW */}
        <div style={{ background: "rgba(255,255,255,0.5)", padding: "15px", borderRadius: "8px" }}>
  <div ref={sigRef}>
            <table
              width="550"
              cellPadding="0"
              cellSpacing="0"
              border="0"
              style={{
                borderCollapse: "collapse",
                fontFamily: "Noto Sans",
                color: "#102a4c"
              }}
            >
              <tbody>
                <tr>
                  {/* LOGO */}
                  <td
                    width="110"
                    align="center"
                    style={{
                      padding: "10px",
                      borderRight: "1px solid #ccc"
                    }}
                  >
                    <img
                      src={LOGO_BASE64}
                      width="150"
                      style={{
                        display: "block",
                        border: 0,
                        maxWidth: "150px"
                      }}
                      alt="RAMP360"
                    />
                  </td>

                  {/* CONTENT */}
                  <td style={{ padding: "10px 15px" }}>
                    <table
                      width="100%"
                      cellPadding="0"
                      cellSpacing="0"
                      border="0"
                    >
                      <tbody>
                        <tr>
                          <td style={{ fontSize: "18px", fontFamily:"Noto Sans", fontWeight: "bold", color:"#102b4e" }}>
                            {data.name.toUpperCase()}
                          </td>
                        </tr>

                        <tr>
                          <td
                            style={{ fontFamily:"Noto Sans",fontSize: "15px",color: "#72bf44",
                              paddingBottom: "10px"}}>
                            {data.title}
                          </td>
                        </tr>

                        <tr>
                          <td style={{ color:"#102b4e",fontFamily:"Noto Sans",fontSize: "16px",fontWeight: "bold" }}>
                            RAMP360 Ground Handling Services Private Limited
                          </td>
                        </tr>

                        {/* PHONE */}
                        <tr>
                          <td style={{ color:"#102b4e",fontFamily:"Noto Sans", paddingTop: "6px" }}>
                           <img src="https://cdn-icons-png.flaticon.com/512/597/597177.png" width="16"
                              style={{ marginRight: 6 }} />
                            {data.phone}
                          </td>
                        </tr>

                        {/* EMAIL */}
                        <tr>
                          <td style={{ color:"#102b4e",fontFamily:"Noto Sans", paddingTop: "3px" }}>
                         <img src="https://cdn-icons-png.flaticon.com/512/732/732200.png" width="16"
                              style={{ marginRight: 6 }} />
                            {data.email}
                          </td>
                        </tr>

                        {/* WEBSITE */}
                        <tr>
                          <td style={{ color:"#102b4e",fontFamily:"Noto Sans", paddingTop: "3px" }}>
                           <img src="https://cdn-icons-png.flaticon.com/512/25/25284.png" width="16" style={{ marginRight: 6 }} />
                            www.ramp360.in
                          </td>
                        </tr>

                        {/* SOCIAL */}
                        <tr>
                          <td style={{ paddingTop: "8px" }}> 
                            <a href="https://maps.app.goo.gl/FjvDmwcM9bpUuACD6">
                              <img src="https://cdn-icons-png.flaticon.com/512/684/684908.png" width="18" style={{ marginRight: 6 }} />
                            </a>
                            <a href="https://www.linkedin.com/company/ramp360/">
                             <img src="https://cdn-icons-png.flaticon.com/512/174/174857.png" width="18" style={{ marginRight: 6 }} />
                            </a>
                            <a href="https://instagram.com/ramp360.in">
                               <img src="https://cdn-icons-png.flaticon.com/512/174/174855.png" width="18" style={{ marginRight: 6 }} />
                            </a>
                            <a href="https://x.com/ramp360_in">
                               <img src="https://cdn-icons-png.flaticon.com/512/5968/5968830.png" width="18" />
                            </a>
                          </td>
                        </tr>

                        {/* CALENDAR */}
                        {data.calendar && (
                          <tr>
                            <td style={{ paddingTop: "8px" }}>
                              <a
                                href={data.calendar}
                                style={{
                                  background: "#102a4c",
                                  color: "#6bbe45",
                                  padding: "6px 10px",
                                  textDecoration: "none",
                                  borderRadius: "4px",
                                  fontSize: "12px"
                                }}
                              >
                                Book My Calendar
                              </a>
                            </td>
                          </tr>
                        )}
                      </tbody>
                    </table>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>

          <button onClick={downloadHTML}>Download</button>
        </div>
      </div>
    </div>
      
      {/* Footer */}
      <footer
  style={{
    position: "fixed",
    bottom: 0,
    left: 0,
    width: "100%",
    height: "36px",           // 👈 reserve space
    lineHeight: "36px",
    textAlign: "center",
    fontSize: "12px",
    color: "#fff",
    background: "rgba(0,0,0,0.4)",
    zIndex: 10
  }} >
  Powered by <strong>AKL Holdings Inc.</strong> © 2026
</footer>

    </div>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

